//
// NOTE on pre-implementation state: DeactivateModal still shows a "Reassign 4 open
// items" checkbox (fabricated count) for EVERY user regardless of role, calls
// `store.setStatus(u.email, "Deactivated")` (no `reassign_book_to`, no `updateStaff`),
// and Wizard.tsx's Role step Notice has no `leavingRm` branch. Every assertion below
// targets the FE-15 contract (role-scoped, real counts, reassign_book_to on the real
// patch call) and is expected to fail until FE-8/FE-9/FE-15 land.
import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it, vi, beforeEach } from "vitest";

const mockUseAdminStore = vi.fn();
vi.mock("@/lib/admin/AdminStoreContext", () => ({
  useAdminStore: () => mockUseAdminStore(),
}));
vi.mock("sonner", () => ({ toast: { success: vi.fn(), error: vi.fn(), warning: vi.fn() } }));

beforeEach(() => {
  document.body.innerHTML = '<div id="content-overlay-root"></div>';
  mockUseAdminStore.mockReset();
});

const RM_WITH_BOOK = {
  firebase_uid: "rm-1", email: "rm1@megaannum.ai", name: "Jane Doe", role: "RM",
  department: "RM", phone_number: null, status: "ACTIVE", last_sign_in_at: "2026-07-01T00:00:00Z",
  override_count: 0, client_count: 23, open_ticket_count: 4,
};
const RM_NO_BOOK = { ...RM_WITH_BOOK, firebase_uid: "rm-2", client_count: 0, open_ticket_count: 0 };
const OTHER_RM = { ...RM_WITH_BOOK, firebase_uid: "rm-3", name: "Active Receiver", client_count: 5 };
const PC_USER = { ...RM_WITH_BOOK, firebase_uid: "pc-1", role: "PC", client_count: null, open_ticket_count: null };

describe("FE-15 DeactivateModal", () => {
  function mountStore(staff: unknown[]) {
    const updateStaff = vi.fn(async () => true);
    mockUseAdminStore.mockReturnValue({ staff, ovrFor: () => [], updateStaff });
    return updateStaff;
  }

  it("positive: for an RM with a book, the picker renders with real client_count/open_ticket_count numbers, lists only other active RMs", async () => {
    mountStore([RM_WITH_BOOK, OTHER_RM, PC_USER]);
    const { DeactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<DeactivateModal user={RM_WITH_BOOK as never} onClose={vi.fn()} />);
    expect(screen.getByText(/23 clients/)).toBeInTheDocument();
    expect(screen.getByText(/4 open tickets/)).toBeInTheDocument();
    expect(screen.queryByText(/4 open items/i)).not.toBeInTheDocument(); // the old fabricated count
  });

  it("positive: on confirm, sends status:DEACTIVATED plus reassign_book_to once a receiver is chosen", async () => {
    const updateStaff = mountStore([RM_WITH_BOOK, OTHER_RM]);
    const { DeactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<DeactivateModal user={RM_WITH_BOOK as never} onClose={vi.fn()} />);
    fireEvent.click(screen.getByText(/pick a receiving rm/i));
    fireEvent.click(screen.getByText(/active receiver/i));
    fireEvent.click(screen.getByRole("button", { name: /deactivate account/i }));
    expect(updateStaff).toHaveBeenCalledWith(
      "rm-1",
      expect.objectContaining({ status: "DEACTIVATED", reassign_book_to: "rm-3" }),
    );
  });

  it("negative: confirm is disabled until a receiver is chosen", async () => {
    mountStore([RM_WITH_BOOK, OTHER_RM]);
    const { DeactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<DeactivateModal user={RM_WITH_BOOK as never} onClose={vi.fn()} />);
    expect(screen.getByRole("button", { name: /deactivate account/i })).toBeDisabled();
  });

  it("negative: no picker renders for a PC user, and the patch carries no reassign_book_to", async () => {
    const updateStaff = mountStore([PC_USER, RM_WITH_BOOK]);
    const { DeactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<DeactivateModal user={PC_USER as never} onClose={vi.fn()} />);
    expect(screen.queryByText(/pick a receiving rm/i)).not.toBeInTheDocument();
    fireEvent.click(screen.getByRole("button", { name: /deactivate account/i }));
    expect(updateStaff).toHaveBeenCalledWith("pc-1", expect.not.objectContaining({ reassign_book_to: expect.anything() }));
  });

  it("negative: no picker renders for an RM whose client_count is 0", async () => {
    mountStore([RM_NO_BOOK, OTHER_RM]);
    const { DeactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<DeactivateModal user={RM_NO_BOOK as never} onClose={vi.fn()} />);
    expect(screen.queryByText(/pick a receiving rm/i)).not.toBeInTheDocument();
    expect(screen.getByRole("button", { name: /deactivate account/i })).not.toBeDisabled();
  });

  it("negative: a 409 from updateStaff keeps the modal open with the picker visible and surfaces the server message", async () => {
    const { toast } = await import("sonner");
    const updateStaff = vi.fn(async () => false);
    mockUseAdminStore.mockReturnValue({ staff: [RM_WITH_BOOK, OTHER_RM], ovrFor: () => [], updateStaff });
    const onClose = vi.fn();
    const { DeactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<DeactivateModal user={RM_WITH_BOOK as never} onClose={onClose} />);
    fireEvent.click(screen.getByText(/pick a receiving rm/i));
    fireEvent.click(screen.getByText(/active receiver/i));
    fireEvent.click(screen.getByRole("button", { name: /deactivate account/i }));
    expect(onClose).not.toHaveBeenCalled();
    expect(screen.getByText(/pick a receiving rm/i)).toBeInTheDocument();
    void toast;
  });

  it("invariant: the receiver list never contains the user being deactivated, a non-ACTIVE user, or a non-RM", async () => {
    const deactivatedRm = { ...OTHER_RM, firebase_uid: "rm-4", name: "Gone Already", status: "DEACTIVATED" };
    mountStore([RM_WITH_BOOK, OTHER_RM, PC_USER, deactivatedRm]);
    const { DeactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<DeactivateModal user={RM_WITH_BOOK as never} onClose={vi.fn()} />);
    fireEvent.click(screen.getByText(/pick a receiving rm/i));
    expect(screen.queryByText(/jane doe/i)).not.toBeInTheDocument(); // self
    expect(screen.queryByText(/gone already/i)).not.toBeInTheDocument(); // deactivated
    expect(screen.queryByText(RM_WITH_BOOK.name)).not.toBeInTheDocument();
  });

  it("the 'not undone on reactivation' line is present whenever the picker is", async () => {
    mountStore([RM_WITH_BOOK, OTHER_RM]);
    const { DeactivateModal } = await import("@/components/admin/enroll/LifecycleModals");
    render(<DeactivateModal user={RM_WITH_BOOK as never} onClose={vi.fn()} />);
    expect(screen.getByText(/not.*undone on reactivation/i)).toBeInTheDocument();
  });
});

describe("FE-15 Wizard.tsx Role step — the same handover Notice in edit mode", () => {
  async function renderRoleStep(draft: Record<string, unknown>) {
    mockUseAdminStore.mockReturnValue({ eff: vi.fn(() => "NONE"), totalPages: 16, grantedFor: vi.fn(() => 0) });
    const { Wizard } = await import("@/components/admin/enroll/Wizard");
    return render(
      <Wizard
        draft={draft as never} step={1} setStep={vi.fn()} patchDraft={vi.fn()}
        openGroups={[]} onToggleGroup={vi.fn()} onLeave={vi.fn()} onSubmit={vi.fn()}
      />,
    );
  }

  it("positive: editing an RM with a book to MOBO reveals the picker inside the Role step's Notice", async () => {
    await renderRoleStep({
      mode: "edit", orig: "rm-1", origRole: "RM", first: "Jane", last: "Doe", email: "rm1@megaannum.ai",
      phone: "", start: "27 Jul 2026", addr: "", dept: "", role: "MOBO", ovr: {}, ovrExpiry: "90 days",
      notify: false, client_count: 23, open_ticket_count: 4, reassign_book_to: null,
    });
    expect(screen.getByText(/pick a receiving rm/i)).toBeInTheDocument();
    expect(screen.getByText(/23 clients/)).toBeInTheDocument();
  });

  it("negative: editing that RM back to RM shows the ordinary Notice (no picker)", async () => {
    await renderRoleStep({
      mode: "edit", orig: "rm-1", origRole: "RM", first: "Jane", last: "Doe", email: "rm1@megaannum.ai",
      phone: "", start: "27 Jul 2026", addr: "", dept: "", role: "RM", ovr: {}, ovrExpiry: "90 days",
      notify: false, client_count: 23, open_ticket_count: 4, reassign_book_to: null,
    });
    expect(screen.queryByText(/pick a receiving rm/i)).not.toBeInTheDocument();
    expect(screen.getByText(/changing the role swaps the whole standing access set/i)).toBeInTheDocument();
  });
});
